import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"Request Replay","description":"Re-send captured HTTP requests with optional modifications using NectoProxy.","frontmatter":{"title":"Request Replay","description":"Re-send captured HTTP requests with optional modifications using NectoProxy."},"headers":[],"relativePath":"features/request-replay.md","filePath":"features/request-replay.md","lastUpdated":1772297611000}'),n={name:"features/request-replay.md"};function r(o,e,l,p,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="request-replay" tabindex="-1">Request Replay <a class="header-anchor" href="#request-replay" aria-label="Permalink to &quot;Request Replay&quot;">​</a></h1><p>Request Replay lets you <strong>re-send any captured HTTP request</strong> directly from the NectoProxy UI. You can replay the request exactly as it was originally sent, or modify the URL, method, headers, and body before replaying. The response to the replayed request is captured and can be compared against the original response.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><strong>Select a request</strong> from the traffic list</li><li><strong>Open the replay panel</strong> from the request&#39;s detail view or context menu</li><li><strong>Optionally modify</strong> the request (URL, method, headers, body)</li><li><strong>Send</strong> the replayed request</li><li><strong>View the response</strong> alongside the original for comparison</li></ol><p>NectoProxy sends the replayed request through the proxy, which means all active features apply -- rules, breakpoints, network conditioning, and upstream proxy settings affect replayed requests just as they affect live traffic.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The replayed request appears in the traffic list as a new entry, clearly marked as a replay. This maintains a complete audit trail of all traffic, including replays.</p></div><h2 id="replaying-from-the-traffic-list" tabindex="-1">Replaying from the Traffic List <a class="header-anchor" href="#replaying-from-the-traffic-list" aria-label="Permalink to &quot;Replaying from the Traffic List&quot;">​</a></h2><h3 id="quick-replay" tabindex="-1">Quick Replay <a class="header-anchor" href="#quick-replay" aria-label="Permalink to &quot;Quick Replay&quot;">​</a></h3><p>To replay a request without modifications:</p><ol><li>Right-click on a request in the traffic list</li><li>Select <strong>Replay Request</strong></li><li>The request is immediately re-sent with the same method, URL, headers, and body</li><li>The response appears as a new entry in the traffic list</li></ol><h3 id="replay-with-modifications" tabindex="-1">Replay with Modifications <a class="header-anchor" href="#replay-with-modifications" aria-label="Permalink to &quot;Replay with Modifications&quot;">​</a></h3><p>To modify a request before replaying:</p><ol><li>Click on a request in the traffic list to open the detail panel</li><li>Click the <strong>Replay</strong> button</li><li>The replay editor opens with all the original request details pre-filled</li><li>Make your modifications</li><li>Click <strong>Send</strong> to replay the modified request</li></ol><h2 id="what-you-can-modify" tabindex="-1">What You Can Modify <a class="header-anchor" href="#what-you-can-modify" aria-label="Permalink to &quot;What You Can Modify&quot;">​</a></h2><p>The replay editor lets you change any aspect of the request before it is sent.</p><h3 id="url" tabindex="-1">URL <a class="header-anchor" href="#url" aria-label="Permalink to &quot;URL&quot;">​</a></h3><p>Edit the full request URL, including the scheme, host, path, and query parameters:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Original:  https://api.example.com/v1/users?page=1&amp;limit=10</span></span>
<span class="line"><span>Modified:  https://api.example.com/v1/users?page=2&amp;limit=50</span></span></code></pre></div><h3 id="http-method" tabindex="-1">HTTP Method <a class="header-anchor" href="#http-method" aria-label="Permalink to &quot;HTTP Method&quot;">​</a></h3><p>Change the HTTP method to test how the server handles different verbs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Original:  GET</span></span>
<span class="line"><span>Modified:  POST</span></span></code></pre></div><h3 id="headers" tabindex="-1">Headers <a class="header-anchor" href="#headers" aria-label="Permalink to &quot;Headers&quot;">​</a></h3><p>Add, modify, or remove request headers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Original headers:</span></span>
<span class="line"><span>  Authorization: Bearer old-token-123</span></span>
<span class="line"><span>  Accept: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Modified headers:</span></span>
<span class="line"><span>  Authorization: Bearer new-token-456</span></span>
<span class="line"><span>  Accept: application/xml</span></span>
<span class="line"><span>  X-Debug: true</span></span></code></pre></div><h3 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h3><p>Edit the request body content. For JSON bodies, the editor provides syntax highlighting and validation:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Original body</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jane Doe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;jane@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Modified body</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jane Doe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;jane.doe@newdomain.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><details class="details custom-block"><summary>Advanced Body Editing</summary><p>The body editor supports:</p><ul><li><strong>JSON</strong> with syntax highlighting and pretty-printing</li><li><strong>Form data</strong> with key-value pair editing</li><li><strong>Plain text</strong> with a simple text editor</li><li><strong>Raw binary</strong> with hex input</li></ul><p>The Content-Type header is automatically updated if you change the body format, or you can set it manually.</p></details><h2 id="comparing-original-vs-replayed-response" tabindex="-1">Comparing Original vs. Replayed Response <a class="header-anchor" href="#comparing-original-vs-replayed-response" aria-label="Permalink to &quot;Comparing Original vs. Replayed Response&quot;">​</a></h2><p>After replaying a request, you can compare the replayed response with the original to identify differences. NectoProxy provides a comparison view that shows:</p><table tabindex="0"><thead><tr><th>Comparison</th><th>What is Shown</th></tr></thead><tbody><tr><td><strong>Status code</strong></td><td>Whether the status code changed</td></tr><tr><td><strong>Response headers</strong></td><td>Added, removed, or modified headers</td></tr><tr><td><strong>Response body</strong></td><td>Content differences (JSON-aware for structured data)</td></tr><tr><td><strong>Timing</strong></td><td>Response time comparison</td></tr></tbody></table><p>This comparison is powered by the same engine used in the <a href="./request-comparison.html">Request Comparison</a> feature, with visual highlighting of differences.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The compare view is particularly useful for verifying that API behavior has not changed after a deployment. Replay a request from before the deployment and compare the response to identify any differences.</p></div><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="regression-testing" tabindex="-1">Regression Testing <a class="header-anchor" href="#regression-testing" aria-label="Permalink to &quot;Regression Testing&quot;">​</a></h3><p>Verify that an API endpoint still returns the same response after a code change or deployment:</p><ol><li>Capture requests to the endpoint before the change</li><li>After the change is deployed, replay the captured requests</li><li>Compare original and replayed responses</li><li>Investigate any differences</li></ol><h3 id="debugging-intermittent-issues" tabindex="-1">Debugging Intermittent Issues <a class="header-anchor" href="#debugging-intermittent-issues" aria-label="Permalink to &quot;Debugging Intermittent Issues&quot;">​</a></h3><p>Reproduce an intermittent error by replaying the exact request that triggered the issue:</p><ol><li>Capture the failing request in NectoProxy</li><li>Replay it multiple times to see if the error is consistent or intermittent</li><li>If intermittent, monitor the response patterns to identify correlating factors (timing, server state)</li><li>Modify headers or body to narrow down the cause</li></ol><h3 id="testing-input-variations" tabindex="-1">Testing Input Variations <a class="header-anchor" href="#testing-input-variations" aria-label="Permalink to &quot;Testing Input Variations&quot;">​</a></h3><p>Test how an API handles different inputs without manually constructing requests from scratch:</p><ol><li>Capture a working request to the API</li><li>Use replay-with-modifications to change specific input values</li><li>Test edge cases: <ul><li>Empty strings</li><li>Missing required fields</li><li>Extremely long values</li><li>Special characters</li><li>Boundary values for numeric fields</li></ul></li><li>Observe how the server responds to each variation</li></ol><h3 id="authentication-testing" tabindex="-1">Authentication Testing <a class="header-anchor" href="#authentication-testing" aria-label="Permalink to &quot;Authentication Testing&quot;">​</a></h3><p>Test different authentication scenarios:</p><ol><li>Capture an authenticated API request</li><li>Replay with the original token to verify it still works</li><li>Replay with an expired token to test error handling</li><li>Replay with a token for a different user to test authorization</li><li>Replay without the Authorization header to test unauthenticated access</li></ol><h3 id="rate-limit-testing" tabindex="-1">Rate Limit Testing <a class="header-anchor" href="#rate-limit-testing" aria-label="Permalink to &quot;Rate Limit Testing&quot;">​</a></h3><p>Verify rate limiting behavior:</p><ol><li>Capture a request to a rate-limited endpoint</li><li>Replay it rapidly multiple times</li><li>Observe when the server starts returning <code>429 Too Many Requests</code></li><li>Check the response headers for rate limit information (e.g., <code>X-RateLimit-Remaining</code>)</li></ol><h2 id="multiple-replays" tabindex="-1">Multiple Replays <a class="header-anchor" href="#multiple-replays" aria-label="Permalink to &quot;Multiple Replays&quot;">​</a></h2><p>You can replay the same request multiple times. Each replay creates a new entry in the traffic list, so you can compare responses across multiple replays to check for consistency.</p><details class="details custom-block"><summary>Example: Consistency Testing</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Original request  --&gt; 200 OK  {&quot;balance&quot;: 100.00}</span></span>
<span class="line"><span>Replay #1        --&gt; 200 OK  {&quot;balance&quot;: 100.00}</span></span>
<span class="line"><span>Replay #2        --&gt; 200 OK  {&quot;balance&quot;: 100.00}</span></span>
<span class="line"><span>Replay #3        --&gt; 200 OK  {&quot;balance&quot;: 95.00}   &lt;-- Different!</span></span></code></pre></div><p>If a replayed response differs from the original or from previous replays, this indicates that server state has changed or that the response is non-deterministic. This insight is valuable for debugging data consistency issues.</p></details><h2 id="interaction-with-other-features" tabindex="-1">Interaction with Other Features <a class="header-anchor" href="#interaction-with-other-features" aria-label="Permalink to &quot;Interaction with Other Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Rules Engine</strong></td><td>Active rules apply to replayed requests. A mock rule will return the mock response for a replay, just as it would for a live request.</td></tr><tr><td><strong>Breakpoints</strong></td><td>Active breakpoints can intercept replayed requests, allowing you to modify them further during replay.</td></tr><tr><td><strong>Network Conditioning</strong></td><td>Active network conditioning profiles affect replayed requests.</td></tr><tr><td><strong>Sessions</strong></td><td>Replayed requests are added to the active session.</td></tr><tr><td><strong>HAR Export</strong></td><td>Replayed requests are included in HAR exports.</td></tr><tr><td><strong>Annotations</strong></td><td>You can annotate replayed requests just like any other entry.</td></tr></tbody></table><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Request replay sends a real HTTP request to the target server. Be mindful when replaying requests that trigger side effects (creating records, sending emails, processing payments, etc.). Always verify that you are replaying against a safe environment.</p></div>`,56)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
